window.SAQ_PAPER_QUESTIONS["2017-2-nsw"]=[{"number":1,"title":"","stemText":"A 54 year old woman presents to your tertiary ED with a 24 hour history of haemoptysis,\ngetting worse in the last 4 hours. She has no known history of systemic illness and is on no medications. On arrival she is coughing up 5-10 ml of bright red blood every 10 mins.","parts":[{"id":"a","label":"Part A","prompt":"List the key components of your assessment (8 marks)"},{"id":"b","label":"Part B","prompt":"List 5 causes of massive haemoptysis (5 marks)\nWhile in the resus room, she suddenly starts to cough up larger volumes of blood, now\naround 50 ml every 5 minutes."},{"id":"c","label":"Part C","prompt":"List 7 key interventions to perform since this increase in haemoptysis (7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Should include at least 2 components from each section below</td></tr><tr><td colspan=\"2\">• Primary survey</td></tr><tr><td>o</td><td>Manage in resus</td></tr><tr><td>o</td><td>Assessment of airway patency</td></tr><tr><td>o</td><td>Assessment of adequate oxygenation and ventilation (RR, Sats, VBG or ABG)</td></tr><tr><td>o</td><td>Assessment of haemodynamics, IV access etc</td></tr><tr><td colspan=\"2\">• History</td></tr><tr><td>o</td><td>History for underlying causes (lung disease, cardiac, FHx, autoimmune, infective,</td></tr><tr><td colspan=\"2\">PE, smoking, recent procedures)</td></tr><tr><td>o</td><td>Medication history (anticoagulants), illicit drug use</td></tr><tr><td>o</td><td>Travel history, country of origin</td></tr><tr><td colspan=\"2\">• Exam</td></tr><tr><td>o</td><td>As above</td></tr><tr><td>o</td><td>Exclusion of other sources of bleeding eg pharynx</td></tr><tr><td colspan=\"2\">• Investigations:</td></tr><tr><td colspan=\"2\">o Bloods: FBC, G and H, X-match if Hb low/anticipate large volume bleed, coags,</td></tr><tr><td colspan=\"2\">EUC, LFTs</td></tr><tr><td colspan=\"2\">o UA, ECG</td></tr><tr><td colspan=\"2\">o ABG/VBG to assess gas exchange, lactate</td></tr><tr><td colspan=\"2\">o CXR looking for bronchiectasis, infection, space-occupying lesions, vascular</td></tr><tr><td colspan=\"2\">malformations, abscess, PE</td></tr><tr><td colspan=\"2\">NSW Fellowship Course - SAQ trial paper 2017.2</td></tr><tr><td colspan=\"2\">o CT chest with contrast</td></tr><tr><td colspan=\"2\">o ECHO (mitral stenosis, shunting from AVM)</td></tr><tr><td colspan=\"2\">ii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Bronchiectasis</div><div class=\"answer-line\">• Tuberculosis</div><div class=\"answer-line\">• Cancer: bronchogenic lung , metastases to lung</div><div class=\"answer-line\">• Immune lung disease (Goodpasture’s, Wegener’s granulomatosis)</div><div class=\"answer-line\">• Vascular malformations eg AVM</div><div class=\"answer-line\">• Thoracic aortic aneurysm</div><div class=\"answer-line\">• Lung abscess</div><div class=\"answer-line\">• Necrotising lung infections eg S.aureus</div><div class=\"answer-line\">• Iatrogenic (post-procedure)</div><div class=\"answer-line\">• PE esp septic emboli</div><div class=\"answer-line\">• Coagulopathy</div><div class=\"answer-line\">• Cardiac eg mitral stenosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• Re-assess ABCs</div><div class=\"answer-line\">• Fluid resuscitation</div><div class=\"answer-line\">• Consider transfusion of PRBC/activation massive transfusion protocol as required</div><div class=\"answer-line\">• Airway clearance</div><div class=\"answer-line\">• Oxygen to maintain adequate oxygenation</div><div class=\"answer-line\">• Airway management: intubation if haemoptysis continuing/prior to bronchoscopy</div><div class=\"answer-line\">(potentially difficult), poor gas exchange, losing airway patency</div><div class=\"answer-line\">• If side of bleeding identified consider selective intubation of unaffected side and/or</div><div class=\"answer-line\">nurse with bleeding lung dependent</div><div class=\"answer-line\">• Tranexamic acid nebulised neat:  500mg to 1g, can be repeated</div><div class=\"answer-line\">• Reversal of anticoagulation if not done before</div><div class=\"answer-line\">• Urgent bronchoscopy</div><div class=\"answer-line\">• Possible interventional radiology procedure if in IR-capable centre for angiography and</div><div class=\"answer-line\">embolization of bleeding point</div><div class=\"answer-line\">• Keep NBM</div><div class=\"answer-line\">• Antibiotics to cover likely cause (Pseudomonas unless other likely organism):</div><div class=\"answer-line\">Ciprofloxacin 750mg q12h po or piperacillin/tazobactam 4.5g q6h iv</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 38 year old male patient presents to your urban ED with sudden onset occipital headache\nand vomiting whilst lifting weights at the gym.\n\nVital signs\n\nGCS 14\nP 100 bpm\n\nBP 180/70 mmHg\n\nTemp 36 deg C","parts":[{"id":"a","label":"Part A","prompt":"Interpret the CT images (4 marks) CT IMAGES ARE SHOWN IN THE PROPS BOOKLET, PAGE 3"},{"id":"b","label":"Part B","prompt":"Outline 5 management priorities (5 marks)"},{"id":"c","label":"Part C","prompt":"List 4 strategies to minimize abnormalities in intracranial pressure if this patient was\nintubated (4 marks)"}],"propPages":["asset:imgc1d8928ac7ec625dd5","asset:imgb71bb236a5323913ab"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Extensive SAH in the suprasellar cistern (-&gt; prepontine cistern) -&gt; foramen magnum &amp;</div><div class=\"answer-line\">brainstem</div><div class=\"answer-line\">• Left greater than right supraseller cistern</div><div class=\"answer-line\">• Consistent with circle of Willis aneurysm rupture</div><div class=\"answer-line\">• Early temporal horn dilatation indicative early hydrocephalus</div><div class=\"answer-line\">• Risk / early obstructive hydrocephalus (given temporal horn dilatation or presence of</div><div class=\"answer-line\">blood around brainstem / FM)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Place in resus/monitoring and 15 min neuro obs</div><div class=\"answer-line\">• Analgesia, antiemetic - appropriate</div><div class=\"answer-line\">• NBM</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• Aggressive BP control – aim &lt; 140 systolic, appropriate agent – hydralazine example</div><div class=\"answer-line\">• Head up 30 degree</div><div class=\"answer-line\">• Euglycaemia, euthermia</div><div class=\"answer-line\">• Discussion with neuro surgical centre</div><div class=\"answer-line\">• Liaise with retrieval</div><div class=\"answer-line\">• Prepare for intubation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 4 strategies to minimize abnormalities in intracranial pressure if this patient was</div><div class=\"answer-line\">intubated (4 marks)</div><div class=\"answer-line\">• Head up 30 degrees</div><div class=\"answer-line\">• Avoid ETT tube tie - tape instead</div><div class=\"answer-line\">• Fentanyl premed prior to intubation</div><div class=\"answer-line\">• Normal oxygenation / sodium</div><div class=\"answer-line\">• Avoid hypo/hyperventilation</div><div class=\"answer-line\">• Mannitol / hypertonic saline</div><div class=\"answer-line\">• Thiopentone coma</div><div class=\"answer-line\">• Ca channel blockers to avoid vasospasm</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 54 year old lady presents with alcohol intoxication. 2 hours after arrival you are asked to review her as she is increasingly drowsy.\n\nVital signs\n\nHR 75 bpm\n\nBP 102/64 mmHg\n\nSaO2 93% RA\n\nGCS 9\n\nTemp 36.5 deg C","parts":[{"id":"a","label":"Part A","prompt":"List 5 differentials for her condition (5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 relevant findings on the ECG (3 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 4"},{"id":"c","label":"Part C","prompt":"List 4 immediate life threats following a propranolol overdose and a specific treatment\nfor each (8 marks) Life threat Specific treatment"}],"propPages":["asset:img87e59a57d50081a105"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Tox</div><div class=\"answer-line\">o Antidepressants - TCA (tachy more likely)</div><div class=\"answer-line\">o Sedative - benzos, opiates</div><div class=\"answer-line\">o Cardiac - clonidine, beta blocker, antiarrhythmics</div><div class=\"answer-line\">o Alcohol</div><div class=\"answer-line\">o Recreational - heroin, GHB</div><div class=\"answer-line\">• Head injury</div><div class=\"answer-line\">• Sepsis</div><div class=\"answer-line\">• Metabolic - hypoglycaemia, addisonian</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• B Blocker effects:</div><div class=\"answer-line\">o Prolonged PR, note not yet bradycardic</div><div class=\"answer-line\">• Sodium channel blocker:</div><div class=\"answer-line\">o Broad QRS (&gt;100ms)</div><div class=\"answer-line\">o Right axis deviation of the terminal QRS in aVR</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>List 4 immediate life threats following a propranolol overdose and a specific treatment</td><td>for each (8 marks)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are asked to review a 3 month old male who was brought in by ambulance with his\nmother following an unresponsive episode at home. The infant became floppy and did not appear to breathe for almost 20 seconds.","parts":[{"id":"a","label":"Part A","prompt":"List 4 pertinent features in the history (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis (1 mark)"},{"id":"c","label":"Part C","prompt":"List 4 low risk features that need to be satisfied for this diagnosis (4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 indications for admission (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Resuscitation required (e.g., stimulation, mouth-to-mouth, chest compressions)</div><div class=\"answer-line\">• Temporal relationship with feeding, sleep, crying, vomiting, choking, gagging</div><div class=\"answer-line\">• Colour (cyanosis, pallor)</div><div class=\"answer-line\">• Change in tone (including seizure activity)</div><div class=\"answer-line\">• Respiratory symptoms or other intercurrent illness</div><div class=\"answer-line\">• Prematurity (before 37 wk)</div><div class=\"answer-line\">• History of trauma</div><div class=\"answer-line\">• History of prior apnea</div><div class=\"answer-line\">• Prior airway or respiratory difficulties (snoring, stridor)</div><div class=\"answer-line\">• Known reflux</div><div class=\"answer-line\">• Prior feeding difficulties (choking, gagging, coughing with feeds)</div><div class=\"answer-line\">• Immunization status (pertussis)</div><div class=\"answer-line\">• Family History – SIDS, cardiac dysrhythmias/congenital heart disease</div><div class=\"answer-line\">• Medication use, or used by breastfeeding parent</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Brief resolved unexplained event - BRUE (NOT ALTE – guidelines have changed)</div><div class=\"answer-line\">although both acceptable</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Age &gt; 60 days</div><div class=\"answer-line\">• Gestational age &gt;32 weeks and post-conception age &gt;45 weeks</div><div class=\"answer-line\">• First event</div><div class=\"answer-line\">• Duration &lt; 1 minute</div><div class=\"answer-line\">• No CPR by trained medical provider performed</div><div class=\"answer-line\">• No concerning historical features</div><div class=\"answer-line\">• No concerning physical examination findings</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Post-conception age &lt;48 weeks</div><div class=\"answer-line\">• Ill appearing or concerning findings on examination</div><div class=\"answer-line\">• Bronchiolitis or Pertussis with apnoea</div><div class=\"answer-line\">• Suspicion of non-accidental trauma</div><div class=\"answer-line\">• Past medical history that places them at risk for poor outcomes</div><div class=\"answer-line\">• Prolonged central apnoea or more than 1 episode in 24 hours</div><div class=\"answer-line\">• Family history of SIDS or multiple BRUEs</div><div class=\"answer-line\">• Poor follow-up</div><div class=\"answer-line\">• Parental concern/anxiety</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 47 year old male presents with epigastric pain for the past 45 minutes.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the ECG (4 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 5"},{"id":"b","label":"Part B","prompt":"Describe and justify your immediate pharmacological treatment (4 marks)"},{"id":"c","label":"Part C","prompt":"His pain settles with aliquots of fentanyl but the ECG changes persist. You are 90 minutes away from a PCI centre. Describe and justify your reperfusion plan (3 marks)"},{"id":"d","label":"Part D","prompt":"List 5 absolute contraindications to fibrinolysis (5 marks)"},{"id":"e","label":"Part E","prompt":"What constitutes failure of fibrinolysis, suggesting need for a rescue PCI (3 marks)"}],"propPages":["asset:imgb42bb0acbfa2c8427d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• STE &gt; 2mm in the  inferior leads</div><div class=\"answer-line\">• STE III&gt;II</div><div class=\"answer-line\">• ST depression V2, I, AVL</div><div class=\"answer-line\">• Pathological q wave III</div><div class=\"answer-line\">• Inferior STEMI with RV infarct</div><div class=\"answer-line\">• RV infarction is associated with 40% of inferior STEMI’s</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Aspirin 300mg PO</div><div class=\"answer-line\">• Analgesia – any sensible dose of morphine or fentanyl</div><div class=\"answer-line\">• Other anti-platelet and anti-coagulant medications – any of clopidogrel, ticagrelor,</div><div class=\"answer-line\">heparin, enoxaparin in appropriate doses/regimens</div><div class=\"answer-line\">• It is recommended that supplementary oxygen is only administered if the there is</div><div class=\"answer-line\">evidence of hypoxia (Sats &lt; 90% measured by pulse oximeter), aiming for oxygen</div><div class=\"answer-line\">saturations of 94-98% (Nikolaou 2015). Hyperoxia was associated with increase in infarct</div><div class=\"answer-line\">size. Physiological data suggests that hyperoxia leads to oxygen free radical generation</div><div class=\"answer-line\">and a reduction in coronary flow, and increased coronary vascular resistance, ultimately</div><div class=\"answer-line\">adding insult to the already infarcted myocardium (Farquhar 2009).</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• RV infarcts are pre-load dependent, and administration of nitrates causes systemic</div><div class=\"answer-line\">venodilation and therefore a reduction in venous return. The subsequent reduction in</div><div class=\"answer-line\">preload, reduces cardiac output and BP, this could ultimately worsening the ischaemia.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">His pain settles with aliquots of fentanyl but the ECG changes persist. You are 90</div><div class=\"answer-line\">minutes away from a PCI centre. <strong> </strong>Describe and justify your reperfusion plan (3 marks)</div><div class=\"answer-line\">• Thrombolyse</div><div class=\"answer-line\">• He needs thrombolysis. He presented within an hour of his symptoms, and therefore</div><div class=\"answer-line\">should undergo PCI within 60mins. As this is not achievable; recommendations advise he</div><div class=\"answer-line\">should receive thrombolysis, as long as there are no contraindications.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Any prior ICH</div><div class=\"answer-line\">• Known structural cerebral vascular lesion (eg, arteriovenous malformation)</div><div class=\"answer-line\">• Known malignant intracranial neoplasm (primary or metastatic)</div><div class=\"answer-line\">• Ischemic stroke within 3 mo</div><div class=\"answer-line\">• Suspected aortic dissection</div><div class=\"answer-line\">• Active bleeding or bleeding diathesis (excluding menses)</div><div class=\"answer-line\">• Significant closed-head or facial trauma within 3 mo</div><div class=\"answer-line\">• Intracranial or intraspinal surgery within 2 mo</div><div class=\"answer-line\">• For streptokinase, prior treatment within the previous 6 mo</div><div class=\"answer-line\"><strong>Relative contraindications</strong></div><div class=\"answer-line\">• History of chronic, severe, poorly controlled hypertension</div><div class=\"answer-line\">• Significant hypertension on presentation (SBP &gt;180 mm Hg or DBP &gt;110 mm Hg)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• History of prior ischemic stroke &gt;3 mo</div><div class=\"answer-line\">• Dementia</div><div class=\"answer-line\">• Known intracranial pathology not covered in absolute contraindications</div><div class=\"answer-line\">• Traumatic or prolonged (&gt;10 min) CPR</div><div class=\"answer-line\">• Major surgery (&lt;3 wk)</div><div class=\"answer-line\">• Recent (within 2 to 4 wk) internal bleeding</div><div class=\"answer-line\">• Noncompressible vascular punctures</div><div class=\"answer-line\">• Pregnancy</div><div class=\"answer-line\">• Active peptic ulcer</div><div class=\"answer-line\">• Oral anticoagulant therapy</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Failure of ST elevation to reduce by (50% - 75%) at 90 minutes post lysis</div><div class=\"answer-line\">• Persistent pain</div><div class=\"answer-line\">• The absence of chest pain following thrombolytic therapy does not imply reperfusion;</div><div class=\"answer-line\">however persistent ischaemic chest pain indicates failure (de Belder 2001). Cardiogenic</div><div class=\"answer-line\">shock may occur because of the already infarcted myocardium.</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 30 year old man presents following a MBA. As he swerved to avoid a car, his right foot\nimpacted the ground with his knee fully extended. His only complaint is of severe right knee pain and swelling.","parts":[{"id":"a","label":"Part A","prompt":"List 5 relevant findings on the Xray (5 marks)\nXRAYS ARE SHOWN IN THE PROPS BOOKLET, PAGES 6&7"},{"id":"b","label":"Part B","prompt":"List 3 priorities in management (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 anatomical structures that are likely to injured which are not seen on plain Xray\n(4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 specific complications you would look for (3 marks)"}],"propPages":["asset:img15f887328e64765042","asset:img55b5451eb7be17a5a8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Comminuted fracture medial tibial plateau, depressed - Schatzker IV grade</div><div class=\"answer-line\">• Intercondylar extension</div><div class=\"answer-line\">• Posterior displacement of medial tibial plateau</div><div class=\"answer-line\">• Subluxation of knee joint with antero-lateral translocation of tibia relative to femur</div><div class=\"answer-line\">• Lipohaemarthrosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Knee joint relocation – ideally orthopaedic involvement if no time delay – and splinting</div><div class=\"answer-line\">• Analgesia</div><div class=\"answer-line\">• CT angiography of popliteal artery – allow mark only if knee relocation mentioned first</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 4 anatomical structures that are likely to injured which are not seen on plain Xray</div><div class=\"answer-line\">(4 marks)</div><div class=\"answer-line\">• Popliteal artery</div><div class=\"answer-line\">• Peroneal nerve</div><div class=\"answer-line\">• MCL / LCL</div><div class=\"answer-line\">• ACL / PCL</div><div class=\"answer-line\">• Meniscal injury</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Neuro</div><div class=\"answer-line\">o Peroneal nerve injury</div><div class=\"answer-line\">o Loss of foot dorsiflexion</div><div class=\"answer-line\">o Paraesthesia anterolateral shin, dorsum of foot</div><div class=\"answer-line\">• Vascular</div><div class=\"answer-line\">o Ischaemic lower limb</div><div class=\"answer-line\">o Decreased pulses DP / PT – palpable and / or doppler</div><div class=\"answer-line\">o Compartment syndrome</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"This question concerns isolated peripheral seventh nerve palsy and idiopathic Bell’s palsy.","parts":[{"id":"a","label":"Part A","prompt":"List the clinical features of an isolated 7th nerve palsy due to a peripheral lesion (3 marks) List 5 potential causes of an isolated 7th nerve palsy due to a peripheral lesion (5 marks)"},{"id":"b","label":"Part B","prompt":"What treatment should be advised in idiopathic Bell’s palsy (2 marks)"},{"id":"c","label":"Part C","prompt":"What is the prognosis for recovery from idiopathic Bell’s Palsy (2 marks)"},{"id":"d","label":"Part D","prompt":"What factors are associated with a poorer outcome (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Weakness of facial musculature upper and lower</div><div class=\"answer-line\">• May have decreased taste ipsilateral  affecting anterior 2/3 tongue</div><div class=\"answer-line\">• Ipsilateral hyperacusis</div><div class=\"answer-line\">• Ipsilateral reduced tear production</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Cerebropontine angle mass eg acoustic neuroma, facial neuroma, meningioma,</div><div class=\"answer-line\">cholesteatoma, metastasis</div><div class=\"answer-line\">• Temporal bone fracture</div><div class=\"answer-line\">• Parotid disorder or neoplasm</div><div class=\"answer-line\">• Facial laceration</div><div class=\"answer-line\">• Mastoid surgery</div><div class=\"answer-line\">• Acute or chronic suppurative otitis media</div><div class=\"answer-line\">• Malignant otitis externa</div><div class=\"answer-line\">• Guillain Barre syndrome</div><div class=\"answer-line\">• Lyme disease</div><div class=\"answer-line\">• Sarcoidosis</div><div class=\"answer-line\">• Bell’s palsy</div><div class=\"answer-line\">• Ramsay Hunt syndrome</div><div class=\"answer-line\">• Nasopharyngeal malignancy</div><div class=\"answer-line\">• Collagen vascular disease</div><div class=\"answer-line\">• Diabetes</div><div class=\"answer-line\">• Botulism</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• HIV</div><div class=\"answer-line\">• Syphilis</div><div class=\"answer-line\">• Acute porphyrias</div><div class=\"answer-line\">• EBV</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Eye care to prevent corneal exposure; artificial tear 1-2 hourly with lubricating ointment</div><div class=\"answer-line\">at night</div><div class=\"answer-line\">• Steroid therapy; high dose 60mg daily for 5 days then taper</div><div class=\"answer-line\">• Antivirals – controversial, but acceptable</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• 86% complete recovery at 2 months; incomplete paralysis favours a better outcome</div><div class=\"answer-line\">v.</div><div class=\"answer-line\">What factors are associated with a poorer outcome (2 marks)</div><div class=\"answer-line\">• Pregnancy</div><div class=\"answer-line\">• Diabetes</div><div class=\"answer-line\">• Associated taste disorder</div><div class=\"answer-line\">• Older age</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 3 year old girl is en route by ambulance after drowning in a family pool.","parts":[{"id":"a","label":"Part A","prompt":"List 5 factors which indicate a poor prognosis for this patient (5 marks)"},{"id":"b","label":"Part B","prompt":"Outline your preparation for the patient’s arrival (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• No CPR&gt;10 minutes</div><div class=\"answer-line\">• Submersion &gt;5 minutes</div><div class=\"answer-line\">• Time to first breath &gt;30 minutes</div><div class=\"answer-line\">• Coma/ cardiac arrest at scene</div><div class=\"answer-line\">• GCS 3</div><div class=\"answer-line\">• pH&lt;7.1</div><div class=\"answer-line\">• Coma on arrival</div><div class=\"answer-line\">• Other co morbidities – injury, type of water (fresh vs salt), NAI</div><div class=\"answer-line\">Prognostic scores</div><div class=\"answer-line\">Orlowski scale</div><div class=\"answer-line\">&lt; 3 factors = 90% chance good recovery</div><div class=\"answer-line\">&gt;3 factors = 5% recovery</div><div class=\"answer-line\">Age &lt; 3 years</div><div class=\"answer-line\">Submersion &gt; 5 minutes</div><div class=\"answer-line\">No CPR &gt; 10min</div><div class=\"answer-line\">Coma on arrival</div><div class=\"answer-line\">pH &lt; 7.1</div><div class=\"answer-line\">Conn and Modell – 2 hour post immersion conscious level – if alert GCS &gt;15, then good</div><div class=\"answer-line\">outcome with no neurological deficit =100%, if category 3 (flaccid, GCS 3) &lt; 20% good</div><div class=\"answer-line\">outcome</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Department: adequate staffing / patient flow of rest of department, handover as</div><div class=\"answer-line\">required</div><div class=\"answer-line\">• Resuscitation bay: paediatric trolley and equipment available including IO needle and</div><div class=\"answer-line\">ETT, heaters</div><div class=\"answer-line\">• Staff: resuscitation team with clear delineation of roles (team leader, airway/drugs)</div><div class=\"answer-line\">• Notify paediatric and anaesthetic team / social work for family / staff for CPR available</div><div class=\"answer-line\">• Weight estimation – age x 2 +8=14kg</div><div class=\"answer-line\">• Drug estimation – adrenaline 0.1mL/kg of 1:10000=1.4ml</div><div class=\"answer-line\">o Fluid 20ml/kg bolus = 280ml</div><div class=\"answer-line\">o Glucose 10%dextrose 2ml/kg 28ml</div><div class=\"answer-line\">o 4j/kg shock -56j</div><div class=\"answer-line\">o Atropine 0.02mg/kg</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 32 year old female G1P0 at 30 weeks gestation presents to ED with constant epigastric\npain and headache.\n\nVital signs\n\nGCS 14\nP 100 bpm\n\nBP 170/100 mmHg\n\nTemp 36.8 deg C","parts":[{"id":"a","label":"Part A","prompt":"List your differential diagnosis (4 marks)"},{"id":"b","label":"Part B","prompt":"She then has a generalised seizure. List your treatment priorities (5 marks)"},{"id":"c","label":"Part C","prompt":"Name the labelled parts of the CTG (3 marks) A CTG IS SHOWN IN THE PROPS BOOKLET, PAGE 8 A B C"}],"propPages":["asset:imgdfb1dc838bed1dfd08"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Pre-eclampsia</div><div class=\"answer-line\">• Pancreatitis</div><div class=\"answer-line\">• Acute cholecystitis</div><div class=\"answer-line\">• Gastritis</div><div class=\"answer-line\">• Others</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Urgent O&amp;G attendance</div><div class=\"answer-line\">• Ensure airway patency/O2</div><div class=\"answer-line\">• Left lateral/wedge</div><div class=\"answer-line\">• IV access</div><div class=\"answer-line\">• Seizure control – Midazolam 2.5 mg IV stat, repeat in 5 minutes if required and MgSO4:</div><div class=\"answer-line\">4g IV over 10 minutes then 1g/hr infusion</div><div class=\"answer-line\">• Seek and treat hypoglycaemia</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• BP control: Hydralazine 5-10mg IV over 10 minutes – repeat in 20min or Labetalol 10-</div><div class=\"answer-line\">20mg IV over 5 minutes q 5min</div><div class=\"answer-line\">• Steroids: Betamethasone (2 doses) 12mg  IM,  24 hours apart</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">A</div><div class=\"answer-line\">B</div><div class=\"answer-line\">C</div><div class=\"answer-line\">• A Baseline heart rate – 138</div><div class=\"answer-line\">• B Late deceleration</div><div class=\"answer-line\">• C Uterine contraction</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"Many opportunities to provide preventative health interventions exist in the ED.","parts":[{"id":"a","label":"Part A","prompt":"Briefly define “primary prevention” and “secondary prevention” (2 marks) Primary prevention: Secondary prevention:"},{"id":"b","label":"Part B","prompt":"List the 4 components of the CAGE questionnaire (4 marks)"},{"id":"c","label":"Part C","prompt":"For each category below, list 3 indicators that a woman may be a victim of Domestic Violence (6 marks) Physical Indicators Behavioural indicators"},{"id":"d","label":"Part D","prompt":"In what circumstances should a report of Domestic Violence be made to Police irrespective of the victim’s wishes (3 marks)"},{"id":"e","label":"Part E","prompt":"Other than alcohol and Domestic Violence screening, list 5 public health interventions currently carried out in Emergency Departments - provide an explanation or example for each (5 marks) Public Health intervention type Explanation/Example"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Many opportunities to provide preventative health interventions exist in the Emergency</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• C – have you ever felt you should CUT down on your drinking?</div><div class=\"answer-line\">• A – have people ANNOYED you by criticising your drinking?</div><div class=\"answer-line\">• G – have you ever felt bad or GUILTY about your drinking?</div><div class=\"answer-line\">• E – have you ever had a drink first thing in the morning to steady your nerves or get rid</div><div class=\"answer-line\">of a hangover (EYE opener)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>For each category below, list 3 indicators that a woman may be a victim of Domestic</td><td>Violence (6 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">In what circumstances should a report of Domestic Violence be made to Police</div><div class=\"answer-line\">irrespective of the victim’s wishes (3 marks)</div><div class=\"answer-line\">Where Domestic Violence poses a significant risk to an individual or the public, reports to</div><div class=\"answer-line\">Police must be made, even where this is against the wishes of the victim. Examples:</div><div class=\"answer-line\">• Serious injuries have been inflicted e.g broken bones, stab/gunshot wounds</div><div class=\"answer-line\">• The perpetrator has access to a weapon and has threatened any person or caused a</div><div class=\"answer-line\">reasonable person to fear for their personal safety</div><div class=\"answer-line\">• An immediate risk to any individual/s or the public exists</div><div class=\"answer-line\">• An offence has occurred on Health Service premises</div><div class=\"answer-line\">• Health staff have been threatened</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Other than alcohol and Domestic Violence screening, list 5 public health interventions</td><td>currently carried out in Emergency Departments – provide an explanation or example</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"This question concerns pre-hospital assessment and decompression of pneumothorax.","parts":[{"id":"a","label":"Part A","prompt":"In the pre-hospital setting, list 3 advantages and 3 disadvantages of ultrasound in confirming pneumothorax (6 marks)"},{"id":"b","label":"Part B","prompt":"Write brief notes on the pros and cons of needle decompression vs finger thoracostomy (6 marks)"},{"id":"c","label":"Part C","prompt":"List 4 clinical signs or symptoms of a tension pneumothorax (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>In the pre-hospital setting, list 3 advantages and 3 disadvantages of ultrasound in</td><td>confirming pneumothorax (6 marks)</td><td>• Pros: Fast, no radiation, portable, accurate with training (high spec. + sensitivity),</td></tr><tr><td>potentially avoids unnecessary intervention</td><td>• Cons: Requires training, ambient bright light may make interpretation difficult, patient</td><td>access may be challenging, subcutaneous emphysema may cause artefact</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Write brief notes on the pros and cons of needle decompression vs finger</td></tr><tr><td colspan=\"2\">thoracostomy (6 marks)</td></tr><tr><td colspan=\"2\">NSW Fellowship Course - SAQ trial paper 2017.2</td></tr><tr><td>Needle decompression</td><td>Finger thoracostomy</td></tr><tr><td>Rapid, can be done whilst patient trapped</td><td>Need 360 degree access, not rapid</td></tr><tr><td>Temporising only, may be ineffective</td><td>Definitive</td></tr><tr><td>Landmark accuracy prone to error</td><td>Landmarks also prone to error but larger</td></tr><tr><td colspan=\"2\">area of safety of insertion</td></tr><tr><td>Can cause iatrogenic vascular injury and</td><td>Can be associated with iatrogenic intercostal</td></tr><tr><td>bleeding</td><td>vessel/nerve injury and bleeding</td></tr><tr><td>Lower level of training required to perform</td><td>Requires training to perform</td></tr><tr><td>Patient doesn’t require sedation for</td><td>Patient requires at least LA and often some</td></tr><tr><td>procedure</td><td>sedation for procedure</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Hypoxia, hypotension, agitation, dyspnoea, shock, ipsilateral dullness to percussion,</div><div class=\"answer-line\">ispilateral decreased air entry, contralateral hyper-expansion appearance</div><div class=\"answer-line\">• Tracheal deviation not a reliable localising sign</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"An 18 year old female presents to ED after an ingestion of 200 x 62.5mcg digoxin tablets.\nShe has no past medical history of note and weighs 65kg.","parts":[{"id":"a","label":"Part A","prompt":"What is the potential lethal dose of digoxin (1 mark)"},{"id":"b","label":"Part B","prompt":"List the clinical features of ACUTE digoxin toxicity (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 relevant investigations you would perform in this patient (3 marks)"},{"id":"d","label":"Part D","prompt":"List the indications for the use of digoxin immune Fab (Digibind) (5 marks)"},{"id":"e","label":"Part E","prompt":"What dose of digoxin immune Fab would be required for this patient (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• &gt;10mg in adult or 4mg in child OR</div><div class=\"answer-line\">• &gt;10 times daily dose</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• GI – nausea, vomiting, abdo pain</div><div class=\"answer-line\">• CVS – bradycardia including heart block, slow AF, dysrhythmias including ectopic,</div><div class=\"answer-line\">bigeminy, SVT, VT, hypotension</div><div class=\"answer-line\">• CNS – lethargy, confusion, delirium</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• ECG</div><div class=\"answer-line\">• UEC</div><div class=\"answer-line\">• Digoxin level</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Cardiac arrest</div><div class=\"answer-line\">• Life threatening cardiac arrhythmias</div><div class=\"answer-line\">• Ingestion of &gt;10mg in an adult or &gt;4mg in a child</div><div class=\"answer-line\">• Serum digoxin level &gt;15nmol/mL</div><div class=\"answer-line\">• Serum K &gt; 5mmol/L</div><div class=\"answer-line\">v.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Known dose – no. ampoules = ingested dose (mg) x 0.8 x 2 (based on one ampoule</div><div class=\"answer-line\">binding 0.5mg digoxin)</div><div class=\"answer-line\">• OR 5 ampoules if HD stable, 10 if unstable</div><div class=\"answer-line\">• Controversial with recent evidence suggesting minimal benefit</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 56 year old man presents to the ED with priapism. He states he has had an erection\nwithout arousal for the past 7 hours.","parts":[{"id":"a","label":"Part A","prompt":"What complications can occur if this condition is untreated (2 marks)"},{"id":"b","label":"Part B","prompt":"Describe the role of cavernosal blood gas analysis in determining the cause of priapism (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 other investigations that might be indicated. Provide a brief justification for each (4 marks)"},{"id":"d","label":"Part D","prompt":"You are in a small hospital with no urological service. Outline your emergency department management of this condition (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">What complications can occur if this condition is untreated [2 marks]</div><div class=\"answer-line\">• Erectile dysfunction</div><div class=\"answer-line\">• Dysfiguration of penis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Describe the role of cavernosal blood gas analysis in determining the cause of priapism</div><div class=\"answer-line\">(2 marks)</div><div class=\"answer-line\">• Gas analysis on cavernosal blood aspirated from the corpus cavernosum differentiates</div><div class=\"answer-line\">ischaemic from non-ischaemic forms of priapism. Ischaemic type needs urgent</div><div class=\"answer-line\">intervention. Typical pH cut-off is 7.25</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>List 2 other investigations that might be indicated. Provide a brief justification for each</td><td>(4 marks)</td></tr><tr><td>• FBC/film - haematological causes - myeloma, sickle cell disease, leukaemia, thalassaemia</td><td>• Biochemistry – to seek causes like CKI/dialysis, gout, hyperlipidaemia, diabetes</td></tr><tr><td>• Malaria films</td><td>• Doppler ultrasound – as an alternative to gas analysis to differentiate ischaemic/non-</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">You are in a small hospital with no urological service. Outline your emergency</div><div class=\"answer-line\">department management of this condition [3 marks]</div><div class=\"answer-line\">• Ice blocks/local pressure</div><div class=\"answer-line\">• Analgesia: perform penile block</div><div class=\"answer-line\">• Aspirate up to 50mL blood from each corpus cavernosum via butterfly needle and</div><div class=\"answer-line\">syringe</div><div class=\"answer-line\">• Injection with phenylephrine (1ml/1000mcg in 9ml normal saline), inject 0.5ml into</div><div class=\"answer-line\">corpus cavernosa and apply pressure</div><div class=\"answer-line\">• Other sympathomimetic/alpha-agonist drugs acceptable – must be in a dilute solution</div><div class=\"answer-line\">• Oral terbutaline 5-10mg</div><div class=\"answer-line\">• Consult and transfer for urological care</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 12 year old male presents after being kicked in the mouth whilst playing rugby at school.","parts":[{"id":"a","label":"Part A","prompt":"Describe the injuries in the photo (3 marks) A CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 9"},{"id":"b","label":"Part B","prompt":"Outline your stepwise approach to systemic analgesia in this child (3 marks)"},{"id":"c","label":"Part C","prompt":"What are the goals of treatment for this dental injury (3 marks)"},{"id":"d","label":"Part D","prompt":"You decide to use IV ketamine for procedural sedation. What are the significant adverse effects of ketamine (3 marks)"},{"id":"e","label":"Part E","prompt":"The parents are not keen on ketamine. Describe your choice of regional anesthesia for this child (2 marks)"}],"propPages":["asset:imgc39a2739233ec534c0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Subluxed 1:1 (R upper 1st incisor)</div><div class=\"answer-line\">• Extruded or Lateral luxation 2:1 (Lt upper 1st incisor)</div><div class=\"answer-line\">• Lip contusion</div><div class=\"answer-line\">• Alveolar Fracture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Stepwise implies increasing strength / may allow for keeping NBM and skip oral agents</div><div class=\"answer-line\">Drugs listed should include dose based on a weight estimation of about 35 kg</div><div class=\"answer-line\">• Paracetamol 700mg (20mg/kg) or 525mg (15mg /kg)</div><div class=\"answer-line\">• Ibuprofen 350mg (10mg/kg)</div><div class=\"answer-line\">• IN Fentanyl 1.5-2mcg / kg (52.5-70mcg) Repeat after 5min</div><div class=\"answer-line\">• IV Morphine 0.1mg/kg (3.5mg) repeated at 5min</div><div class=\"answer-line\">• Ketamine IM/IV</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Stabilise the teeth (prevent aspiration risk)</div><div class=\"answer-line\">• Approximate anatomical position to prevent further ligament injury/aid healing</div><div class=\"answer-line\">• Provide advice on definitive management with Dentist</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• Exclude associated injuries</div><div class=\"answer-line\">• Analgesia</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">You decide to use IV ketamine for procedural sedation. What are the significant adverse</div><div class=\"answer-line\">effects of ketamine (3 marks)</div><div class=\"answer-line\">• Laryngospasm</div><div class=\"answer-line\">• Emergence reactions</div><div class=\"answer-line\">• Transient Apnea</div><div class=\"answer-line\">• Emesis</div><div class=\"answer-line\">• Allergy</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">The parents are not keen on ketamine. Describe your choice of regional anesthesia for</div><div class=\"answer-line\">this child (2 marks)</div><div class=\"answer-line\">• Field block (Supraperiosteal)  – 1% Lignocaine into mucobuccal fold above each tooth</div><div class=\"answer-line\">• Bilateral Infraorbital nerve blocks</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 40 year old man is brought to your ED after being swept into rough water whilst rock\nfishing in the middle of winter. On examination you notice a contusion to the right forehead.\n\nVital signs\n\nGCS 5\n\nHR 48 bpm\n\nBP 105/70 mmHg\n\nRR 12 bpm\n\nSaO2 94% RA\n\nTemp 28 deg C","parts":[{"id":"a","label":"Part A","prompt":"List the key features on the ECG (2 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 10"},{"id":"b","label":"Part B","prompt":"List 5 important aspects to consider during the initial resuscitation (5 marks)"},{"id":"c","label":"Part C","prompt":"Describe the methods you would employ to rewarm this patient noting specific triggers for any invasive measures (6 marks)"}],"propPages":["asset:img7dad8ac0deda0bf9cc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Sinus bradycardia, Osborne J waves, shivering artefact (SR, normal axis rate 40/m)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• A – and C spine protection/collar</div><div class=\"answer-line\">• B – will need RSI/ intubation for airway protection with in-line immobilisation; and for</div><div class=\"answer-line\">CT head to be performed in safe/stable manner</div><div class=\"answer-line\">• C – insert iv line and start giving warm iv fluids</div><div class=\"answer-line\">• D – neuroprotection</div><div class=\"answer-line\">• E – start rewarming with external measures; gentle handling of patient (esp if rhythm</div><div class=\"answer-line\">becomes AF, can precipitate VF otherwise)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Describe the methods you would employ to rewarm this patient noting specific triggers</div><div class=\"answer-line\">for any invasive measures (6 marks)</div><div class=\"answer-line\">• Rewarming</div><div class=\"answer-line\">o Remove wet clothing, dry patient (Passive Rewarming)</div><div class=\"answer-line\">o Peripheral Active Warming - Warm blankets, BAIR hugger, ?Radiant heater –</div><div class=\"answer-line\">(purported link to peripheral vasodilation, hypotension and core temp afterdrop</div><div class=\"answer-line\">not clinically important)</div><div class=\"answer-line\">o Consider Central Active Warming</div><div class=\"answer-line\">▪ warmed (40-46C) humidified inspired gases (1 C/h; 1.5°C/h ET tube)</div><div class=\"answer-line\">▪ warm IV fluids (42C)  (only give if need fluids, prevents cooling rather</div><div class=\"answer-line\">than promotes warming) – use Level 1 fluid warmer</div><div class=\"answer-line\">▪ body cavity lavage with 40C fluid e.g. peritoneal (3C/h), gastric, bladder,</div><div class=\"answer-line\">right-sided thoracic lavage (3-6C/h – use 2 ICCs for continuous flow)</div><div class=\"answer-line\">▪ RRT</div><div class=\"answer-line\">▪ ECMO/ bypass (9-18C/h)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 18 month old immunised boy presents to ED with a 7 day history of a fever to > 39\ndegrees, poor oral intake and lethargy. On examination, he appears unwell with a blanching rash with some desquamation, a red tongue and bilateral conjunctivitis.","parts":[{"id":"a","label":"Part A","prompt":"List 4 possible diagnoses starting with the most likely (4 marks)"},{"id":"b","label":"Part B","prompt":"List the diagnostic criteria of the most likely diagnosis (5 marks)"},{"id":"c","label":"Part C","prompt":"List 4 important investigations with a rationale for each (4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 possible drug therapies for the most likely condition (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Kawasaki disease</div><div class=\"answer-line\">• Scalded skin syndrome (Staph)</div><div class=\"answer-line\">• Toxic shock syndrome (Strep), other streptococcal infection (e.g. scarlet fever)</div><div class=\"answer-line\">• Steven&#x27;s Johnson syndrome</div><div class=\"answer-line\">• Measles, other viral exanthem</div><div class=\"answer-line\">• Juvenile rheumatoid arthritis</div><div class=\"answer-line\">• Drug reaction</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Fever for at least 5 days + 4/5 of the following:</div><div class=\"answer-line\">• Bilateral (non-purulent) conjunctival injection</div><div class=\"answer-line\">• Mucous membrane changes – reddened or dry cracked lips, strawberry tongue, diffuse</div><div class=\"answer-line\">redness of oral or pharyngeal mucosa</div><div class=\"answer-line\">• Polymorphous rash</div><div class=\"answer-line\">• Peripheral changes – palmar and plantar erythema, oedema, desquamation (usually in</div><div class=\"answer-line\">convalescence)</div><div class=\"answer-line\">• Cervical lymphadenopathy (&gt; 15 mm diameter, usually unilateral, single, non-purulent</div><div class=\"answer-line\">and painful)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Echo:  Cardiac/ coronary artery imaging to determine or exclude dangerous</td><td></td></tr><tr><td>complications of KD: coronary artery aneurysms, ectasia, mitral regurgitation,</td><td></td></tr><tr><td>ventricular dysfunction, pericardial effusion, at least twice: at initial presentation and, if</td><td></td></tr><tr><td>negative, again at 6 - 8 weeks</td><td></td></tr><tr><td>•</td><td>Microbiological assays: Blood cultures +/-  urine culture, exclusion of serious bacterial</td></tr><tr><td>illness or secondary infection</td><td></td></tr><tr><td>•</td><td>Strep A testing (serology /ASOT or Anti DNAase +/-  throat swab), exclude invasive</td></tr><tr><td>/recent Strep infection</td><td></td></tr><tr><td>•</td><td>Measles testing (serology, urine/NPA PCR) to help exclude measles</td></tr><tr><td>•</td><td>FBC /Platelet count/WCC, look for mild normochromic, normocytic anaemia and/or</td></tr><tr><td>thrombocytosis (marked thrombocytosis common in second week of illness)</td><td></td></tr><tr><td>•</td><td>Inflammatory markers (CRP/ESR), raised, non-specific, useful for severity</td></tr><tr><td>assessment/disease monitoring/response</td><td></td></tr><tr><td>•</td><td>LFTs - hypoalbuminaemia and elevated liver enzymes</td></tr><tr><td>•</td><td>ECG - long PR and QT interval and T wave changes</td></tr><tr><td>iv.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• IV immunoglobulin 2 g/kg over 10 hours; preferably within the first 10 days of the illness</div><div class=\"answer-line\">but should also be given to patients diagnosed after 10 days of illness if there is evidence</div><div class=\"answer-line\">of ongoing inflammation - eg fever, raised ESR/CRP)</div><div class=\"answer-line\">• Aspirin 3 - 5 mg/kg once a day for at least 6 to 8 weeks.</div><div class=\"answer-line\">• Some give a higher dose (10mg/kg 8 hourly for the first few days) but this may not add</div><div class=\"answer-line\">nothing over immunoglobulin. (current conjecture between high and low dose)</div><div class=\"answer-line\">• Corticosteroids (it’s a possible Rx option, whose benefit is subject to evolving evidence)</div><div class=\"answer-line\">• Others acceptable: paracetamol, intravenous hydration, anticoagulation for giant or</div><div class=\"answer-line\">multiple coronary aneurysms, fibrinolytics for coronary artery thrombus, influenza</div><div class=\"answer-line\">vaccine to prevent Reye Syndrome in children on long-term aspirin.</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A young man has fallen onto his left hand, which is swollen and generally tender. Neurovascular status is intact.","parts":[{"id":"a","label":"Part A","prompt":"Interpret the Xray (3 marks) AN XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 11"},{"id":"b","label":"Part B","prompt":"Outline 4 priorities in management (4 marks)"},{"id":"c","label":"Part C","prompt":"List 3 long term sequelae (3 marks)"},{"id":"d","label":"Part D","prompt":"The orthopaedic registrar requests your RMO to complete the consent for ORIF. Outline your response (3 marks)"}],"propPages":["asset:imgce4ca3bca4d0c9291e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Perilunate dislocation</div><div class=\"answer-line\">• Scaphoid fracture</div><div class=\"answer-line\">• Appears closed injury, no SC air</div><div class=\"answer-line\">• No immobilisation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Analgesia – appropriate</div><div class=\"answer-line\">• Elevate, immobilisation</div><div class=\"answer-line\">• Early ortho involvement – likely ORIF</div><div class=\"answer-line\">• NBM</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Reduction in hand function/stiffness/OA</div><div class=\"answer-line\">• Chronic pain</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">The orthopaedic registrar requests your RMO to complete the consent for ORIF. Outline</div><div class=\"answer-line\">your response (3 marks)</div><div class=\"answer-line\">• Sensible response, counselling, collegiate etc</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A normally well 24 year old man is brought to your ED with increasing confusion and a\nseizure. A blood gas shows the following.\n\npH\n7.31\n\nPCO2\nmmHg (35-45)\n\nHCO3\nmmol/L (22-28)\n\nNa 109\nmmol/L (135-145)\n\nK\n4.1 mmol/L (3.5-4.2)\n\nCl\nmmol/L (95-110)\n\nGlucose\nmmol/L (3.9-5.8)","parts":[{"id":"a","label":"Part A","prompt":"Detail the specific emergency treatment required and provide treatment aims/endpoints (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 risk factors for the development of Osmotic Demyelination Syndrome (ODS) and\nwrite brief explanatory notes (6 marks)"},{"id":"c","label":"Part C","prompt":"Hypertonic saline is also used in the management of raised intracranial pressure in traumatic brain injury (TBI). What dose/regime would you use and what target endpoints would guide your therapy (4 marks)"},{"id":"d","label":"Part D","prompt":"Briefly outline the advantages/disadvantages of hypertonic saline versus mannitol in TBI (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Detail the specific emergency treatment required and provide treatment</div><div class=\"answer-line\">aims/endpoints (3 marks)</div><div class=\"answer-line\">• Hypertonic saline</div><div class=\"answer-line\">• 3mls/kg of 3% - or sensible dose</div><div class=\"answer-line\">• Over 30 mins - or sensible rate</div><div class=\"answer-line\">• Clinical improvement - cessation of seizures and clinical recovery</div><div class=\"answer-line\">• Raising serum Na and serum osmols by 2-3mmol/L</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List 3 risk factors for the development of Osmotic Demyelination Syndrome (ODS) and</div><div class=\"answer-line\">write brief explanatory notes (6 marks)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• Serum sodium at presentation – most cases of ODS occur when initial [Na] &lt; 105, and</div><div class=\"answer-line\">unusual for ODS to occur if initial Na &gt; 120 mmol/L</div><div class=\"answer-line\">• Duration of hyponatraemia – ODS rarely occurs if hypoNa has developed over only a few</div><div class=\"answer-line\">hours or up to a day (e.g. following ingestion of large volumes of water)</div><div class=\"answer-line\">• Overly rapid correction – the increase over 24 or 48 hours appears more important than</div><div class=\"answer-line\">the hour-by-hour change. Safe 24 hour rise generally said to be about 5 mmol/L per day</div><div class=\"answer-line\">• Other risk factors – especially groups who can develop ODS with less severe hypoNa and</div><div class=\"answer-line\">slower rates of correction</div><div class=\"answer-line\">o Alcoholism</div><div class=\"answer-line\">o Malnutrition</div><div class=\"answer-line\">o Liver disease</div><div class=\"answer-line\">o Hypokalaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypertonic saline is also used in the management of raised intracranial pressure in</div><div class=\"answer-line\">traumatic brain injury (TBI). What dose/regime would you use and what target</div><div class=\"answer-line\">endpoints would guide your therapy (4 marks)</div><div class=\"answer-line\">• Hypertonic saline 3% 150 mL bolus IV or 7.5% 75 mL bolus IV. Can repeat q 2-4 hours</div><div class=\"answer-line\">• Targets/endpoints</div><div class=\"answer-line\">o ICP &lt; 20 mmHg</div><div class=\"answer-line\">o Osmolality 300-320 mOsm/L</div><div class=\"answer-line\">o Sodium 145-150 mmol/L</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Briefly outline the advantages/disadvantages of hypertonic saline versus mannitol in TBI</td><td>(3 marks)</td><td>• No good quality evidence of improved neuro or mortality outcomes for either drug</td></tr><tr><td>• HTS more effective in lowering ICP (failure rate of 16% for HTS vs 35% for mannitol)</td><td>• HTS has a more prolonged effect on ICP</td><td>• HTS “haemodynamically stable” compared to mannitol which causes osmotic diuresis </td></tr><tr><td>hypotension</td><td>NSW Fellowship Course - SAQ trial paper 2017.2</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 20 year old male is brought to your ED with confusion and hyperthermia following a\nmarathon. You think he has exertion related heat stroke.","parts":[{"id":"a","label":"Part A","prompt":"What are the management priorities in this situation (5 marks)"},{"id":"b","label":"Part B","prompt":"What investigations would you perform and why (4 marks) Heat illness affects some groups more than others and non-exertional heat stroke is more common during heat waves."},{"id":"c","label":"Part C","prompt":"Define heat wave (2 marks)"},{"id":"d","label":"Part D","prompt":"List 4 risk factors for classic non-exertional heat stroke (4 marks)"},{"id":"e","label":"Part E","prompt":"List three drugs/medications from different classes that increase the risk of heat stroke and explain the pharmacological reason(s) for the effect for each (6 marks) Medication Explanation"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Remove him from the race/exertion</div><div class=\"answer-line\">• Cooling – shade, spray/fan, remove clothing, ice packs/baths</div><div class=\"answer-line\">• Cautious hydration – PO if able IVF if not</div><div class=\"answer-line\">• Check metabolic function – BSL + Na</div><div class=\"answer-line\">• Seek &amp; treat complications – e.g. rhabdo, seizure, …</div><div class=\"answer-line\">• Consider intubation if not improving (avoid sux)</div><div class=\"answer-line\">• Consider possibility of other competitors having problems</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• EUC – Low Na, High K, Impaired renal function</div><div class=\"answer-line\">• CK – High risk muscle damage and rhabdo</div><div class=\"answer-line\">• Coags/LFTs – Risk of DIC</div><div class=\"answer-line\">• BSL – Metabolic derangement</div><div class=\"answer-line\">• UA – Myoglobinuria</div><div class=\"answer-line\">• ECG – Cardiac arrhythmias</div><div class=\"answer-line\">• Ongoing core rectal temp</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• BOM definition - three days or more of high maximum and minimum temperatures that</div><div class=\"answer-line\">is unusual for that location</div><div class=\"answer-line\">• Acceptable definition should include concept of prolonged period of high temperature</div><div class=\"answer-line\">unusual for that location and/or that results in adverse health effects</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Environmental – Prolonged extreme high temperatures/humidity</div><div class=\"answer-line\">• Situational – Lack of acclimatization, poor Na and H20 intake</div><div class=\"answer-line\">• Patient related – Extremes of age, poor health, malnourished, alcohol, mental health</div><div class=\"answer-line\">• Meds – Psychotropics, serotonergics, anticholinergics, sympathomimetics</div><div class=\"answer-line\">• Medical – Sepsis, dehydration, chronic neurological conditions</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>List three drugs/medications from different classes that increase the risk of heat stroke</td><td></td></tr><tr><td>and explain the pharmacological reason(s) for the effect for each (6 marks)</td><td></td></tr><tr><td>Medication</td><td>Explanation</td></tr><tr><td>•</td><td>Interference with sweating, caused by:</td></tr><tr><td>o Anticholinergics, e.g. tricyclics antidepressants and benztropine</td><td></td></tr><tr><td>o Beta-blockers</td><td></td></tr><tr><td>NSW Fellowship Course - SAQ trial paper 2017.2</td><td></td></tr><tr><td>o Antihistamines</td><td></td></tr><tr><td>o Phenothiazines</td><td></td></tr><tr><td>o Vasoconstrictors</td><td></td></tr><tr><td>•</td><td>Interference with thermoregulation, caused by:</td></tr><tr><td>o Antipsychotics or Neuroleptics (e.g. risperidone, clozapine, olanzapine)</td><td></td></tr><tr><td>o Serotoninergic agonists</td><td></td></tr><tr><td>o Stimulants (Amphetamine, cocaine)</td><td></td></tr><tr><td>o Thyroxin</td><td></td></tr><tr><td>•</td><td>Decreased thirst, caused by:</td></tr><tr><td>o Butyrophenone e.g. haloperidol and droperidol,</td><td></td></tr><tr><td>o Angiotensin-converting enzyme (ACE) inhibitors</td><td></td></tr><tr><td>•</td><td>Dehydration or electrolyte imbalance, caused by:</td></tr><tr><td>o Diuretics (especially loop diuretics)</td><td></td></tr><tr><td>o Any drug causing diarrhoea or vomiting (colchicines, antibiotics, codeine)</td><td></td></tr><tr><td>o Alcohol</td><td></td></tr><tr><td>•</td><td>Reduced renal function, caused by:</td></tr><tr><td>o NSAIDS</td><td></td></tr><tr><td>o Sulphonamides</td><td></td></tr><tr><td>o Indinavir</td><td></td></tr><tr><td>o Cyclosporin</td><td></td></tr><tr><td>•</td><td>Aggravation of heat illness by worsening hypotension, caused by:</td></tr><tr><td>o Vasodilators e.g. nitrates (GTN) and calcium channel blockers</td><td></td></tr><tr><td>o Anti-hypertensives</td><td></td></tr><tr><td>•</td><td>Levels of drug affected by dehydration (possible toxicity for drugs with a narrow</td></tr><tr><td>therapeutic index), caused by:</td><td></td></tr><tr><td>o Digoxin</td><td></td></tr><tr><td>o Lithium</td><td></td></tr><tr><td>o Warfarin</td><td></td></tr><tr><td>o Antiepileptics</td><td></td></tr><tr><td>o Biguanides (e.g. Metformin)</td><td></td></tr><tr><td>o Statins</td><td></td></tr><tr><td>•</td><td>Altered state of alertness, caused by:</td></tr><tr><td>o Any drugs which alter the state of alertness (e.g. alcohol, benzodiazepine,</td><td></td></tr><tr><td>narcotics and many more)</td><td></td></tr><tr><td>NSW Fellowship Course - SAQ trial paper 2017.2</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 20 year old male presents with a 3 day history of lethargy and generalised malaise. He is confused and looks unwell. The following venous blood tests are obtained.\n\npH\n7.08\n\npCO2\nmmHg (35-45)\n\nHCO3\nmmol/L (22-28)\n\nBE\n-22 mmol/L (-3-3)\n\nLactate\nmmol/L (<2.2)\n\nGlucose\nmmol/L (3.9-5.8)\n\nK\n2.7 mmol/L (3.5-4.2)\n\nNa\n160 mmol/L (135-145)\n\nCl\n124 mmol/L (95-110)\n\nCreatinine\nmicromol/L (60-110)\n\nUrea\n5.3 mmol/L (3-8)","parts":[{"id":"a","label":"Part A","prompt":"Interpret the above results, and show any relevant calculations (5 marks)"},{"id":"b","label":"Part B","prompt":"Outline your immediate management priorities (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Severe metabolic acidosis with adequate respiratory compensation</div><div class=\"answer-line\">• High anion gap metabolic acidosis. Likely secondary to DKA given the high glucose</div><div class=\"answer-line\">• Na is high – 160 and even higher when corrected – 160 + (44-10/3) = 171. Likely</div><div class=\"answer-line\">secondary to water loss – glycosuria. Potassium is low – acidaemia usually drive K up, so</div><div class=\"answer-line\">corrected will be even lower.</div><div class=\"answer-line\">• Delta AG/HCO3 – 1</div><div class=\"answer-line\">• Hyperosmolality – (2x160) + 44/18 + 5.3/2.8 = 324</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Move to resus – needs monitoring in view of hypokalaemia and hypernatraemia. Needs</div><div class=\"answer-line\">x2 IVC, may need central access if K drops when resuscitation starts</div><div class=\"answer-line\">• Needs 1 litre NS immediately</div><div class=\"answer-line\">• Start insulin infusion at rate of 0.1 unit per kg/hr. Aim to drop BSL 2-4 per hour</div><div class=\"answer-line\">• K replacement – may need central line. 10mmol/hour</div><div class=\"answer-line\">• Need to monitor K and Na – at risk of seizures with large drops of Na level</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 3 year old boy is brought to ED by his mother with abdominal pain and vomiting. Mum is\nconcerned that he may have ingested some of her iron tablets. She is sure that there are\nmore than 10 tablets missing.","parts":[{"id":"a","label":"Part A","prompt":"List 3 details that will assist your risk stratification (3 marks)"},{"id":"b","label":"Part B","prompt":"Complete the following table (4 marks) Elemental Iron dose Clinical Effect <20mg/kg 20-60mg/kg >60-120mg/kg >120mg/kg"},{"id":"c","label":"Part C","prompt":"List 4 investigations with a rationale for each that you would perform to determine the\nseverity of toxicity (4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 options for decontamination in this child (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Number of tablets ingested (inspect bottle if necessary)</div><div class=\"answer-line\">• Time of ingestion</div><div class=\"answer-line\">• Weight child</div><div class=\"answer-line\">• Amount of elemental iron in each tablet to calculate amount of Fe ingested per kg/body</div><div class=\"answer-line\">weight</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Number of tablets ingested (inspect bottle if necessary)</div><div class=\"answer-line\">• Time of ingestion</div><div class=\"answer-line\">• Weight child</div><div class=\"answer-line\">• Amount of elemental iron in each tablet to calculate amount of Fe ingested per kg/body</div><div class=\"answer-line\">weight</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>List 4 investigations with a rationale for each that you would perform to determine the</td><td></td></tr><tr><td>severity of toxicity (4 marks)</td><td></td></tr><tr><td>NSW Fellowship Course - SAQ trial paper 2017.2</td><td></td></tr><tr><td>• FBC</td><td>Leucocytosis/Thrombocytopaenia</td></tr><tr><td>• EUC</td><td>Renal impairment/K derangements secondary to acidosis</td></tr><tr><td>• Blood glucose</td><td>Hypoglycaemia/Hyperglycaemia</td></tr><tr><td>• Coags</td><td>Bleeding diathesis</td></tr><tr><td>• Blood gas</td><td>Metabolic/lactic acidosis/HAGMA</td></tr><tr><td>• Serum Fe Levels</td><td>Peak at 4-6 hours. No clear correlation between levels and</td></tr><tr><td>toxicity but &gt; 90 micromol/l predictive systemic toxicity</td><td></td></tr><tr><td>• AXR</td><td>Confirming ingestion/planning/monitoring decontamination</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>• UGI Endoscopy</td><td>Consider in large OD if WBI fails.  May require multiple insertions</td></tr><tr><td>• WBI</td><td>PEG solution 250-500mls/hr</td></tr><tr><td>• GI Lavage</td><td>Requires ETT. Useful only within 90 mins ingestion</td></tr><tr><td colspan=\"2\">NSW Fellowship Course - SAQ trial paper 2017.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A woman in late pregnancy is brought to you following a high speed MVA.","parts":[{"id":"a","label":"Part A","prompt":"List three changes in respiratory physiology that occur with pregnancy [3 marks]"},{"id":"b","label":"Part B","prompt":"Complete the table regarding cardiotocographic (CTG) monitoring in trauma (4 marks) Purpose of CTG monitoring Gestation (weeks) from which CTG monitoring is useful Recommended duration of CTG monitoring in trauma Three CTG findings suggesting foetal distress"},{"id":"c","label":"Part C","prompt":"Describe the process of peri-mortem caesarean section [5 marks]"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List three changes in respiratory physiology that occur with pregnancy [3 marks]</div><div class=\"answer-line\">• Tidal volume increases (30-40%)</div><div class=\"answer-line\">• Total lung capacity decreases (5% due to diaphragm elevation)</div><div class=\"answer-line\">• Respiratory rate and minute volume increases (30-40%)</div><div class=\"answer-line\">• pCO2 decreases giving respiratory alkalosis</div><div class=\"answer-line\">• Expiratory reserve volume decreases</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Tidal volume increases (30-40%)</div><div class=\"answer-line\">• Total lung capacity decreases (5% due to diaphragm elevation)</div><div class=\"answer-line\">• Respiratory rate and minute volume increases (30-40%)</div><div class=\"answer-line\">• pCO2 decreases giving respiratory alkalosis</div><div class=\"answer-line\">• Expiratory reserve volume decreases</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Describe the process of peri-mortem caesarean section [5 marks]</div><div class=\"answer-line\">• Make a midline vertical incision from the xyphoid to the symphysis pubis</div><div class=\"answer-line\">• Bluntly separate the rectus muscles down the midline with a finger</div><div class=\"answer-line\">• Open the peritoneum – either bluntly by pulling with your hands or with scissors</div><div class=\"answer-line\">• Make a small incision at the lower end of the uterus, above the reflection of the bladder</div><div class=\"answer-line\">• Insert two fingers, and lift the wall of the uterus away from the foetus. Using scissors,</div><div class=\"answer-line\">cut the uterus to the fundus</div><div class=\"answer-line\">• Remove the infant, clamp and cut the cord, proceed to neonatal resuscitation</div><div class=\"answer-line\">• Remove the placenta manually</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"An 89 year old woman is brought to your tertiary ED with sudden severe chest pain and\ncollapse with transient loss of consciousness.\n\nVital signs\n\nBP 90/- mmHg\n\nHR 50 bpm\n\nGCS 12","parts":[{"id":"a","label":"Part A","prompt":"List 4 potentially life threatening diagnoses (4 marks)"},{"id":"b","label":"Part B","prompt":"What are the three most useful diagnostic tests in this setting (3 marks)"},{"id":"c","label":"Part C","prompt":"What is the major abnormality on this bedside sub-sternal ultrasound image and what is the likely clinical diagnosis (2 marks) AN ULTRASOUND IS SHOWN IN THE PROPS BOOKLET, PAGE 12"},{"id":"d","label":"Part D","prompt":"What two treatment approaches are available (2 marks)"},{"id":"e","label":"Part E","prompt":"The family arrives with an Advance Care Directive stating the patient did not want any lifesaving surgery. Prescribe the PRN meds you would chart for the ward (3 marks)"}],"propPages":["asset:img25e7bf396a145d7330"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• AMI/STEMI</div><div class=\"answer-line\">• Aortic dissection</div><div class=\"answer-line\">• PE</div><div class=\"answer-line\">• AAA rupture</div><div class=\"answer-line\">• Cardiac arrhythmia</div><div class=\"answer-line\">• ACS/non STEMI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• ECG</div><div class=\"answer-line\">• Echo/POCUS</div><div class=\"answer-line\">• CT aortogram +/- pulmonary angiogram</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">What is the major abnormality on this bedside sub-sternal ultrasound image and what is</div><div class=\"answer-line\">the likely clinical diagnosis (2 marks)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Operative: urgent cardiothoracic surgery to replace the ascending aorta. May need</div><div class=\"answer-line\">urgent pericardiocentesis if becomes haemodynamically unstable</div><div class=\"answer-line\">• Non operative, palliative approach</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">The family arrives with an Advance Care Directive stating the patient did not want any</div><div class=\"answer-line\">lifesaving surgery. Prescribe the PRN meds you would chart for the ward (3 marks)</div><div class=\"answer-line\">• Analgesia: morphine 1-2 mg subcut Q3H or hydromorphone or fentanyl</div><div class=\"answer-line\">• Sedative: midazolam 2.5 mg Q3H</div><div class=\"answer-line\">• Anti-secretions: hyoscine 400mcg Q3h or glycopyrrolate</div><div class=\"answer-line\">• Various combinations acceptable but need one from each group</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You are at a peripheral hospital with no maternity facilities when a 16 year old obese girl presents in the second stage of labour. Up until this presentation she was unaware that she was pregnant.","parts":[{"id":"a","label":"Part A","prompt":"List 5 steps you would take to prepare for her deliver (5 marks)\nWithin minutes of arrival the baby’s head is delivered. However, on the next contraction you are unable to deliver the shoulders despite gentle axial traction."},{"id":"b","label":"Part B","prompt":"Name this condition and in what period of time should the baby be delivered to avoid serious foetal hypoxia (2 marks)"},{"id":"c","label":"Part C","prompt":"Describe 3 manoeuvres that may enable the safe delivery of the child (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Any 5 of the below</div><div class=\"answer-line\">• Resuscitation room, get help, staff with midwifery/obstetric experience, 2 teams mother</div><div class=\"answer-line\">and baby,</div><div class=\"answer-line\">• Baby resuscitation equipment and staff, resuscitaire, heater, blankets, bag valve mask-</div><div class=\"answer-line\">on air, dose of adrenaline, correct sized airway, breathing equipment. Umbilical line</div><div class=\"answer-line\">• Mother - monitoring, delivery pack, pain relief, iv access bloods, syntocinon for post-</div><div class=\"answer-line\">delivery, ultrasound to exclude multiple birth?</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Name this condition and in what period of time should the baby be delivered to avoid</div><div class=\"answer-line\">serious foetal hypoxia (2 marks)</div><div class=\"answer-line\">• Shoulder dystocia</div><div class=\"answer-line\">• 5 minutes (&lt;10)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Answer any 3 of the following</div><div class=\"answer-line\">• MacRobert’s manoeuvre - Lie mother flat 2 staff members flex and abduct the hips until</div><div class=\"answer-line\">the thighs are on the abdomen (opens up and straightens the birth canal)</div><div class=\"answer-line\">• Suprapubic pressure; to adduct the foetus’ shoulder and thus narrow the width and to</div><div class=\"answer-line\">rotate the shoulders into the oblique axis (assistant presses from the foetus back in a</div><div class=\"answer-line\">downward and lateral manner)</div><div class=\"answer-line\">• Internal rotation; “vaginal access should be gained posteriorly, into the sacral hollow.</div><div class=\"answer-line\">The whole hand should be entered posteriorly to perform internal rotation or delivery of</div><div class=\"answer-line\">the posterior arm. The woman should be brought to the end of the bed, or the end of</div><div class=\"answer-line\">the bed should be removed, to make vaginal access easier. Delivery can then be</div><div class=\"answer-line\">facilitated by rotation into an oblique diameter or when possible by a full 180 degree</div><div class=\"answer-line\">rotation of the fetal trunk”</div><div class=\"answer-line\">• Delivery of the posterior arm: “The fetal wrist should be grasped and the posterior arm</div><div class=\"answer-line\">should be gently withdrawn from the vagina in a straight line”</div><div class=\"answer-line\">• Episiotomy - mainly to allow for getting the hand in</div><div class=\"answer-line\">• Putting mother in “all fours” position (on hands and knees)</div><div class=\"answer-line\">• Cleidotomy - division of symphysis pubis</div><div class=\"answer-line\">• Zavanelli manoeuvre - pushing the head back in and doing a caesarean</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 4 week old baby presents to your urban ED with a runny nose, mild cough and increased\nwork of breathing over the past 2 days. The child had several episodes where her breathing became slower but this resolved with gentle stimulation. She has not fed for 8 hours.\n\nVital signs\n\nTemp 36.6 deg C\n\nHR\n190 bpm\n\nCR\n3 sec\n\nRR\n70/min\n\nSaO2 93% RA","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses (4 marks)"},{"id":"b","label":"Part B","prompt":"Describe and interpret the CXR (4 marks) A CHEST XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 13"},{"id":"c","label":"Part C","prompt":"Outline your management steps (4 marks)"},{"id":"d","label":"Part D","prompt":"You prepare for intubation. Complete the following table (6 marks)\n\nWeight\n4kg ETT size ETT insertion depth Blade type and size Induction agent and dose Paralytic agent and dose Ventilator settings (TV, RR, Fi02)"}],"propPages":["asset:imgac41064b111ce27ce7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Infective – pneumonia, bronchiolitis, UTI, meningitis</div><div class=\"answer-line\">• Cardiac – duct dependent lesion, non-cyanotic congenital heart disease</div><div class=\"answer-line\">• Surgical – malrotation, intussusception</div><div class=\"answer-line\">• Neurological – seizures</div><div class=\"answer-line\">• Trauma – ICH</div><div class=\"answer-line\">• Endocrine – CAH</div><div class=\"answer-line\">• Metabolic – IEM, hypoglycaemia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• RUL collapse / consolidation, LUL consolidation, NG inserted – needs advancing</div><div class=\"answer-line\">• Diagnosis – pneumonia or bronchiolitis with collapse</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• HFNP – L/kg should be given, ideally include Fi02</div><div class=\"answer-line\">• NG insertion further 2cm</div><div class=\"answer-line\">• IV access – IO if fail</div><div class=\"answer-line\">• Fluid bolus – 10-20mls/kg 0.9%NaCl</div><div class=\"answer-line\">• IV Ab – appropriate with dosing – benpen / cephalosporin</div><div class=\"answer-line\">• NETS call</div><div class=\"answer-line\">• Prepare for intubation given apneas</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Weight</div><div class=\"answer-line\">4kg</div><div class=\"answer-line\">ETT size</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 50 year old female presents with chronic lithium poisoning. Investigations reveal a lithium\nlevel of 3.1 mmol/L, and serum creatinine 180 micromol/L.","parts":[{"id":"a","label":"Part A","prompt":"What is the volume of distribution of lithium (1 mark)"},{"id":"b","label":"Part B","prompt":"List 6 possible signs or symptoms of chronic lithium poisoning (6 marks)"},{"id":"c","label":"Part C","prompt":"Outline the principles of management in this patient (5 marks)"},{"id":"d","label":"Part D","prompt":"List 2 major differences between ACUTE and CHRONIC lithium poisoning (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• 0.7 – 0.9 L/kg</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Tremor, hyperreflexia, agitation, muscle weakness, ataxia</div><div class=\"answer-line\">• Stupor, rigidity, hypertonia, hypotension</div><div class=\"answer-line\">• Coma, convulsions, myoclonus</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div><div class=\"answer-line\">• Manage coma and seizures as required</div><div class=\"answer-line\">• Aim to restore renal function to normal with attention to water and sodium deficits</div><div class=\"answer-line\">• IV fluid resuscitation/hydration with 0.9%NaCl</div><div class=\"answer-line\">• Tox consult/admission</div><div class=\"answer-line\">• Consider haemodialysis in setting of neuro symptoms, and Li level &gt; 2.5</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• GI vs neuro</div><div class=\"answer-line\">• Lethality</div><div class=\"answer-line\">• Elimination ie sufficient hydration in normal renal function vs haemodialysis</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 68 year old male sustains blunt trauma to his right eye from a golf ball.","parts":[{"id":"a","label":"Part A","prompt":"Describe three abnormalities in the image (3 marks) A CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 14"},{"id":"b","label":"Part B","prompt":"List 5 features on assessment that would suggest orbital compartment syndrome (5\nmarks)"},{"id":"c","label":"Part C","prompt":"Describe the steps involved in a lateral canthotomy/cantholysis (8 marks)"}],"propPages":["asset:imgd0e91e00e6d9ca8369"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Extensive subconjunctival haemorrhage</div><div class=\"answer-line\">• Extensive chemosis</div><div class=\"answer-line\">• Dilated pupil</div><div class=\"answer-line\">• Proptosis</div><div class=\"answer-line\">• Periorbital bruising</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List 5 features on assessment that would suggest orbital compartment syndrome (5</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">• Proptosis</div><div class=\"answer-line\">• Rock hard eyeball palpated with eyelid closed</div><div class=\"answer-line\">• Visual acuity. Significantly decrease, rapidly dropping to light perception only</div><div class=\"answer-line\">• Inability to open eye</div><div class=\"answer-line\">• Severe eye pain</div><div class=\"answer-line\">• Limited eye movements</div><div class=\"answer-line\">• Raised IOP &gt;40 mm Hg. Rock hard eye ball to palpation compared to the other side</div><div class=\"answer-line\">• RAPD</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Need to have adequate LA and/or sedation. Inject 1-2 mL local anaesthetic into lateral</div><div class=\"answer-line\">canthus</div><div class=\"answer-line\">• Perform the canthotomy - insert needle holder from lateral canthus towards bony orbit</div><div class=\"answer-line\">and compress this area to devascularise it.</div><div class=\"answer-line\">• Remove needle holder and using scissors cut along the lateral canthus 1-2 cm to the</div><div class=\"answer-line\">bony orbit.</div><div class=\"answer-line\">• Perform cantholysis: Grasp the lateral lower eyelid with toothed forceps. Pull the lower</div><div class=\"answer-line\">eyelid down to visualise the inferior canthal tendon and cut through this with scissors. If</div><div class=\"answer-line\">not visualised the tendon can be identified as a rigid band, like a guitar string,</div><div class=\"answer-line\">“strummed” by the forceps to help locate it.</div><div class=\"answer-line\">• If IOP still high after this cut the superior canthal tendon too by lifting the upper eyelid</div><div class=\"answer-line\">and locating the tendon. Use scissors to cut.</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
